{
  "groups": [
    {
      "group_id": "low_rate_fixed_lock",
      "rule": "rate_type == 'fixed' and origination_year >= 2020.0 and mortgage_rate_pct < 3.5",
      "rationale": "Borrowers who locked in low rates during the pandemic face severe payment shock at renewal and are highly likely to be rate-sensitive."
    },
    {
      "group_id": "vulnerable_high_debt",
      "rule": "insured_flag == False and credit_score_band in ['below_600', '600_659'] and mortgage_balance_cad > 400000",
      "rationale": "Uninsured borrowers with lower credit scores and high balances have limited refinancing options and represent a high retention risk due to potential qualification hurdles."
    },
    {
      "group_id": "stressed_families",
      "rule": "n_children >= 3 and household_income_cad < 75000",
      "rationale": "Large households with limited income have minimal financial slack to absorb rising mortgage costs, making them prone to payment distress."
    },
    {
      "group_id": "variable_rate_exposed",
      "rule": "rate_type == 'variable' and mortgage_rate_pct >= 5.0",
      "rationale": "Borrowers already subjected to significant rate increases are currently experiencing payment pressure and may look for stability elsewhere."
    },
    {
      "group_id": "liquid_asset_wealthy",
      "rule": "td_liquid_deposits_cad > 15000 and has_investments == True",
      "rationale": "Affluent clients with high liquidity and investment portfolios have the easiest path to moving lenders and are the most valuable segment to retain."
    },
    {
      "group_id": "late_cycle_renters",
      "rule": "occupancy_type == 'rental' and origination_year >= 2021.0",
      "rationale": "Investors who purchased recently in a softening housing market may be facing negative cash flow and are likely to re-evaluate their portfolios."
    },
    {
      "group_id": "stable_tenured_owners",
      "rule": "td_tenure_months >= 90 and credit_score_band == '720_plus'",
      "rationale": "Long-term, high-credit borrowers are the most stable group and are likely to stay if offered a competitive loyalty renewal."
    }
  ]
}
